//! Offline repair of initial derived-role selection under mixed instructions.
//! Every contextual history is generated by the frozen parent. Exact first
//! operand labels supervise frames only; they are never observed as response text.
use super::instruction_binding_training::fit_router;
use super::source_routing::SourceRouting;
use super::source_routing_training::{Alternative, Frame};
use super::value_types::{ValueRecord, ValueState, ValueWork};
use super::*;
use std::collections::BTreeSet;

enum Input<'a> {
    Context(&'a OperationTransitionExample),
    Prompt(&'a Document),
}
impl Input<'_> {
    fn setup(&self, parent: &Model) -> Result<Session> {
        match self {
            Self::Context(context) => super::operation_transition::prefix(parent, context),
            Self::Prompt(document) => {
                let mut session = parent.session(Control::Full)?;
                session.observe(parent, BOS)?;
                for token in parent.encode(&document.text)? {
                    session.observe(parent, token)?;
                }
                session.begin_response(parent)?;
                Ok(session)
            }
        }
    }
}
fn candidates(
    values: &ValueState,
    context: &super::typed_routing::TypedContext,
) -> Vec<(ValueAction, ValueRecord, ValueRecord)> {
    (0..272)
        .filter_map(|index| values.proposal(index))
        .filter(|(action, left, right)| {
            matches!(action, ValueAction::Copy | ValueAction::Add)
                && super::joint_admission::legal(*action, left.value, right.value)
                && (*action != ValueAction::Add
                    || !super::typed_routing::alias_self_add(
                        values,
                        *left,
                        *right,
                        context.origins.as_ref(),
                        &mut ValueWork::default(),
                    ))
        })
        .collect()
}
fn action(value: ValueAction) -> usize {
    if value == ValueAction::Copy {
        0
    } else {
        1
    }
}
fn correct(
    target: &MixedOperatorTarget,
    proposal: (ValueAction, ValueRecord, ValueRecord),
) -> bool {
    proposal.0 == target.action && [proposal.1.id, proposal.2.id] == target.operand_ids
}
fn selection_frame(
    parent: &Model,
    session: &Session,
    target: Option<&MixedOperatorTarget>,
) -> Result<Option<Frame>> {
    let values = session
        .values
        .as_ref()
        .ok_or_else(|| Error("mixed initial values absent".into()))?;
    let Some(context) =
        super::typed_routing::context(parent, values, Control::Full, &mut ValueWork::default())
            .filter(|context| !context.literal_component && context.depths.is_some())
    else {
        return Ok(None);
    };
    let options = candidates(values, &context);
    let mut best = super::typed_routing::score(
        parent,
        values,
        None,
        2,
        &context,
        Control::Full,
        &mut ValueWork::default(),
    );
    let mut chosen = None;
    for (index, &(operation, left, right)) in options.iter().enumerate() {
        let score = super::typed_routing::score(
            parent,
            values,
            Some((left, right)),
            action(operation),
            &context,
            Control::Full,
            &mut ValueWork::default(),
        );
        if score > best {
            best = score;
            chosen = Some(index);
        }
    }
    let (features, length) = super::typed_routing::features_with_provenance(
        values,
        None,
        &context.addresses,
        context.depths.as_ref(),
        context.provenance.as_ref(),
        &mut ValueWork::default(),
    );
    let mut alternatives = vec![Alternative {
        features: features[..length].to_vec(),
        codes: vec![],
        action: 2,
        correct: target.is_none() && chosen.is_none(),
    }];
    for (index, &(operation, left, right)) in options.iter().enumerate() {
        let (features, length) = super::typed_routing::features_with_provenance(
            values,
            Some((left, right)),
            &context.addresses,
            context.depths.as_ref(),
            context.provenance.as_ref(),
            &mut ValueWork::default(),
        );
        alternatives.push(Alternative {
            features: features[..length].to_vec(),
            codes: vec![],
            action: action(operation),
            correct: target.map_or(chosen == Some(index), |target| {
                correct(target, (operation, left, right))
            }),
        });
    }
    if alternatives
        .iter()
        .filter(|alternative| alternative.correct)
        .count()
        != 1
    {
        return Err(Error(
            "mixed initial exact target absent or ambiguous".into(),
        ));
    }
    Ok(Some(Frame { alternatives }))
}
impl Model {
    pub(super) fn fit_mixed_initial(
        &self,
        docs: &[MixedOperatorExample],
        preservation: &[OperationTransitionExample],
        prompts: &[Document],
        config: &SourceRoutingConfig,
    ) -> Result<(SourceRouting, serde_json::Value)> {
        config.validate()?;
        if docs.is_empty()
            || docs.len() > 128
            || preservation.len() > 512
            || prompts.len() > 768
            || docs.iter().any(|d| {
                !matches!(d.first.action, ValueAction::Copy | ValueAction::Add)
                    || (d.first.action == ValueAction::Copy
                        && d.first.operand_ids[0] != d.first.operand_ids[1])
            })
        {
            return Err(Error(
                "invalid mixed initial training population or target".into(),
            ));
        }
        let old = self
            .typed_roles
            .as_ref()
            .ok_or_else(|| Error("mixed initial role router absent".into()))?;
        let mut ids = BTreeSet::new();
        let mut receipts = Vec::new();
        for context in docs.iter().map(|d| &d.context).chain(preservation) {
            if context.id.is_empty()
                || !ids.insert(context.id.clone())
                || context.query.len() > 4096
                || context.history.len() > 4
                || context.first_response.len() > 128
                || context
                    .history
                    .iter()
                    .any(|turn| turn.prompt.len() > 4096 || turn.response.len() > 128)
            {
                return Err(Error("invalid mixed initial contextual input".into()));
            }
        }
        for d in docs {
            receipts.push(super::training::receipt(&Document {
                id: d.context.id.clone(),
                text: serde_json::to_string(d).map_err(|e| Error(e.to_string()))?,
            }));
        }
        for d in preservation {
            receipts.push(super::training::receipt(&Document {
                id: d.id.clone(),
                text: serde_json::to_string(d).map_err(|e| Error(e.to_string()))?,
            }));
        }
        for d in prompts {
            if d.id.is_empty() || !ids.insert(d.id.clone()) || d.text.len() > 4096 {
                return Err(Error("invalid mixed initial preservation prompt".into()));
            }
        }
        // Bind the complete scanned prompt population in one canonical manifest,
        // keeping every ID and text while respecting the artifact receipt cap.
        if !prompts.is_empty() {
            let manifest = serde_json::to_vec(prompts).map_err(|e| Error(e.to_string()))?;
            let id = "mixed-initial/preserved-prompt-manifest".to_string();
            if !ids.insert(id.clone()) {
                return Err(Error("mixed prompt manifest ID collision".into()));
            }
            receipts.push(DocumentReceipt {
                id,
                bytes: manifest.len(),
                text_cid: format!("blake3:{}", blake3::hash(&manifest)),
            });
        }
        // Every generated history boundary also uses the shared role router.
        // Preserve each one using its actual frozen-parent prefix and preference.
        let histories: Vec<_> = docs
            .iter()
            .map(|d| &d.context)
            .chain(preservation)
            .flat_map(|d| {
                d.history
                    .iter()
                    .enumerate()
                    .map(move |(i, t)| OperationTransitionExample {
                        id: format!("{}/history/{i}", d.id),
                        history: d.history[..i].to_vec(),
                        query: t.prompt.clone(),
                        first_response: t.response.clone(),
                        next: None,
                    })
            })
            .collect();
        let inputs: Vec<_> = docs
            .iter()
            .map(|d| (Input::Context(&d.context), Some(&d.first)))
            .chain(preservation.iter().map(|d| (Input::Context(d), None)))
            .chain(prompts.iter().map(|d| (Input::Prompt(d), None)))
            .chain(histories.iter().map(|d| (Input::Context(d), None)))
            .collect();
        let mut frames = Vec::new();
        let mut skipped = 0;
        for (input, target) in &inputs {
            let session = input.setup(self)?;
            if let Some(frame) = selection_frame(self, &session, *target)? {
                frames.push(frame);
            } else if target.is_some() {
                return Err(Error(
                    "mixed first target lacks derived-role context".into(),
                ));
            } else {
                skipped += 1;
            }
        }
        if frames.len() > 4096 {
            return Err(Error("mixed initial selection frames exceed4096".into()));
        }
        let (roles, selection) = fit_router(
            self,
            &old.router,
            &mut frames,
            docs.len(),
            &receipts,
            config,
        )?;
        Ok((
            roles,
            serde_json::json!({"parent":self.artifact_cid(),
            "selection":selection,"new_documents":docs.len(),
            "preservation_contexts":preservation.len(),"preservation_prompts":prompts.len(),"preservation_prompt_manifest":"canonical serde_json Vec<Document> in original order, binding every ID and text",
            "history_boundaries_preserved":histories.len(),"non_role_preservation_skipped":skipped,"history_model":"frozen parent",
            "scope":"Offline exact initial Copy/Add operand IDs; frozen-parent ordered derived-role preference preservation including NoOperation; literal routing and admission remain frozen; unchanged serving feature law"}),
        ))
    }
}
